"""Frozen public synthetic tasks and separate grading keys for the comparison."""
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
CASES = []


def add(category, development, holdout, checks, *, artifact=None):
    assert len(checks) == 6
    index = len(CASES) + 1
    for split, prompt in [("development", development), ("holdout", holdout)]:
        CASES.append({"id": f"{split[0].upper()}{index:02}", "category": category, "split": split,
                      "prompt": prompt, "artifact": artifact,
                      "checks": [{"id": f"c{i+1}", "requirement": value} for i,value in enumerate(checks)]})
    # Index uses category order, not number of variants.


