def build():
    # Stable case IDs are determined by sorted category, independently of add() internals.
    categories = sorted({c["category"] for c in CASES})
    for item in CASES:
        item["id"] = ("D" if item["split"] == "development" else "H") + f"{categories.index(item['category'])+1:02}"
    assert len(categories) == 30 and len(CASES) == 60
    public = [{k:v for k,v in c.items() if k!="checks"} for c in CASES]
    grading = [{"id": c["id"], "category": c["category"], "split":c["split"], "checks":c["checks"]} for c in CASES]
    destination = Path(__file__).parent
    for name, values in [("tasks.json", public), ("rubrics.json", grading)]:
        path = destination / name
        path.write_text(json.dumps(values,indent=2,ensure_ascii=False)+"\n",encoding="utf-8",newline="\n")
    checksums = {name:hashlib.sha256((destination/name).read_bytes()).hexdigest() for name in ["tasks.json","rubrics.json"]}
    (destination/"freeze.json").write_text(json.dumps({"schema_version":1,"categories":30,"variants":2,"cases":60,"checks_per_case":6,"sha256":checksums},indent=2)+"\n",encoding="utf-8")
    print(json.dumps(checksums,indent=2))


if __name__ == "__main__":
    build()
